p=Path('app/infrastructure/application/starter_projects.py');s=p.read_text(encoding='utf-8').replace('from app.domains.application.packages import ApplicationPackage','from app.domains.application.packages import ApplicationPackage\nfrom app.domains.application.sandbox import ExecutionMode, SandboxPolicy');s=s.replace('{"responsive-hero": "responsive_hero", "pricing-grid": "pricing_grid"}','{"responsive-hero": "responsive_hero", "pricing-grid": "pricing_grid",\n     "broken-signup-validation": "broken_signup_validation", "product-filter": "product_filter"}');s=s.replace('if set(data) != {','if set(data) - {"sandbox"} != {');s=s.replace('protected_paths=tuple(data["protected_paths"]),','protected_paths=tuple(data["protected_paths"]),\n                sandbox=SandboxPolicy(**data["sandbox"]) if data.get("sandbox") else None,');s=s.replace('if package.defaults.build_command != ("node", "build.mjs"):', 'expected_command = ("sandbox", "build") if package.sandbox else ("node", "build.mjs")\n            if package.defaults.build_command != expected_command:');s=s.replace('source = self.starter_dir(name)','source = self.starter_dir(name)\n            if package.sandbox:\n                for required in ("package.json", "package-lock.json", "tsconfig.json", "src/main.tsx", "index.html"):\n                    if not self._confined(source / required).is_file():\n                        raise ValueError("Missing executable starter file")\n                lock = json.loads((source / "package-lock.json").read_text(encoding="utf-8"))\n                if lock.get("lockfileVersion") != 3:\n                    raise ValueError("Executable package requires lockfile v3")');p.write_text(s,encoding='utf-8')
